import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for matrix multiplication (FP32)
kernel_source = """
__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < M * N) {
        int i = idx / N;
        int j = idx % N;
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[i * K + k] * B[k * N + j];
        }
        C[idx] = sum;
    }
}
"""

# Custom CUDA function wrapper
function_source_matmul = """
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto M = A.size(0);
    auto K = A.size(1);
    auto N = B.size(1);

    auto C = torch::zeros_like(A);

    const int block_size = 256;
    const int num_blocks = (M * N + block_size - 1) / block_size;

    matmul_kernel<<<num_blocks, block_size>>>(A.data_ptr<float>(), B.data_ptr<float()>, C.data_ptr<float()>, M, K, N);

    return C;
}
"""

matmul_cuda_source = kernel_source + "\n\n" + function_source_matmul

# Load the custom CUDA operator
matmul_cuda = load_inline(
    name="matmul_cuda",
    cpp_sources="torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);",
    cuda_sources=matmul_cuda_source,
    functions=["matmul_cuda"],
)

# Optimized model that replaces torch.matmul with the custom CUDA operator
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.matmul_cuda = matmul_cuda

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul_cuda(A, B)
